<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_login();
$id=(int)($_GET['id']??0);
$album=['title'=>'','artist'=>'','album_artist'=>'','release_year'=>null,'genre'=>'','label_name'=>'','copyright_text'=>'','description'=>'','cover_file'=>null];
if($id){require_album_access($id);$s=$pdo->prepare('SELECT * FROM albums WHERE id=?');$s->execute([$id]);$album=$s->fetch()?:$album;}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='remove_cover'){
    verify_csrf();
    if(!$id){flash('danger',t('text.album.nicht.gefunden'));redirect('admin/index.php');}
    $s=$pdo->prepare('SELECT cover_file FROM albums WHERE id=?');$s->execute([$id]);$coverFile=$s->fetchColumn();
    $s=$pdo->prepare('UPDATE albums SET cover_file=NULL WHERE id=?');$s->execute([$id]);
    if($coverFile){
        $coverPath=dirname(__DIR__).'/uploads/covers/'.basename((string)$coverFile);
        if(is_file($coverPath)){@unlink($coverPath);}
    }
    flash('success',t('text.cover.wurde.geloscht'));
    redirect('admin/album_edit.php?id='.$id);
}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'save_album')==='save_album'){
    verify_csrf();
    try{
        $cover=$album['cover_file'];
        if(!empty($_FILES['cover']['name'])){$cover=upload_file($_FILES['cover'],dirname(__DIR__).'/uploads/covers',['image/jpeg','image/png','image/webp'],10*1024*1024);}
        if($id){$s=$pdo->prepare('UPDATE albums SET title=?,artist=?,album_artist=?,release_year=?,genre=?,label_name=?,copyright_text=?,description=?,cover_file=? WHERE id=?');$year=(int)($_POST['release_year']??0);$year=$year>0?$year:null;$s->execute([trim($_POST['title']),trim($_POST['artist']),trim($_POST['album_artist']??''),$year,trim($_POST['genre']??''),trim($_POST['label_name']??''),trim($_POST['copyright_text']??''),trim($_POST['description']),$cover,$id]);}
        else{$s=$pdo->prepare('INSERT INTO albums(owner_user_id,title,artist,album_artist,release_year,genre,label_name,copyright_text,description,cover_file) VALUES(?,?,?,?,?,?,?,?,?,?)');$year=(int)($_POST['release_year']??0);$year=$year>0?$year:null;$s->execute([(int)current_user()['id'],trim($_POST['title']),trim($_POST['artist']),trim($_POST['album_artist']??''),$year,trim($_POST['genre']??''),trim($_POST['label_name']??''),trim($_POST['copyright_text']??''),trim($_POST['description']),$cover]);$id=(int)$pdo->lastInsertId();}
        flash('success',t('text.albumdaten.gespeichert.jetzt.konnen.die.titel.hochgeladen.werden'));
        redirect('admin/album_edit.php?id='.$id);
    }catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/album_edit.php'.($id?'?id='.$id:''));}
}

if($_SERVER['REQUEST_METHOD']==='POST' && in_array(($_POST['action']??''),['add_collaborator','remove_collaborator','delete_album'],true)){
    verify_csrf(); require_album_owner_or_admin($id); $action=$_POST['action'];
    if($action==='add_collaborator'){
        $userId=(int)($_POST['user_id']??0);
        if($userId>0){$s=$pdo->prepare('INSERT IGNORE INTO album_collaborators(album_id,user_id) SELECT ?,id FROM users WHERE id=? AND is_active=1 AND id<>(SELECT owner_user_id FROM albums WHERE id=?)');$s->execute([$id,$userId,$id]);if($s->rowCount()>0&&isset($_POST['send_invite'])){$u=$pdo->prepare('SELECT username,email FROM users WHERE id=?');$u->execute([$userId]);$recipient=$u->fetch();if($recipient&&$recipient['email']){try{send_system_mail($recipient['email'],t('mail.collaboration_subject',replace:['album'=>$album['title']]),collaboration_mail_html($recipient['username'],$album,base_url('admin/album_edit.php?id='.$id),!empty($album['cover_file'])?base_url('uploads/covers/'.rawurlencode((string)$album['cover_file'])):null));}catch(Throwable $e){}}}flash('success',t('text.nutzer.wurde.zur.internen.mitverwaltung.hinzugefugt'));}
        redirect('admin/album_edit.php?id='.$id.'#interne-freigabe');
    }
    if($action==='remove_collaborator'){$s=$pdo->prepare('DELETE FROM album_collaborators WHERE album_id=? AND user_id=?');$s->execute([$id,(int)($_POST['user_id']??0)]);flash('success',t('text.interne.freigabe.wurde.entfernt'));redirect('admin/album_edit.php?id='.$id.'#interne-freigabe');}
    if($action==='delete_album'){
        $pdo->prepare('UPDATE albums SET deleted_at=NOW() WHERE id=?')->execute([$id]);
        flash('success','Album wurde in den Papierkorb verschoben und wird nach 30 Tagen endgültig gelöscht.');redirect('admin/index.php');
    }
}
if($_SERVER['REQUEST_METHOD']==='POST' && in_array(($_POST['action']??''),['create_share','update_share','delete_share','email_share'],true)){
    verify_csrf();$action=$_POST['action'];
    if($action==='create_share'){
        $token=create_short_share_token($pdo);$expires=trim($_POST['expires_at']??'')?:null;$hash=trim($_POST['password']??'')!==''?password_hash($_POST['password'],PASSWORD_DEFAULT):null;
        $s=$pdo->prepare('INSERT INTO shares(album_id,token,label,password_hash,expires_at,allow_download) VALUES(?,?,?,?,?,?)');
        $s->execute([$id,$token,trim($_POST['label']??''),$hash,$expires,!empty($_POST['allow_download'])?1:0]);flash('success','Freigabelink erstellt.');
    }elseif($action==='update_share'){
        $shareId=(int)($_POST['share_id']??0);$expires=trim($_POST['expires_at']??'')?:null;
        if(trim($_POST['password']??'')!==''){$s=$pdo->prepare('UPDATE shares SET label=?,password_hash=?,expires_at=?,allow_download=? WHERE id=? AND album_id=?');$s->execute([trim($_POST['label']??''),password_hash($_POST['password'],PASSWORD_DEFAULT),$expires,!empty($_POST['allow_download'])?1:0,$shareId,$id]);}
        else{$s=$pdo->prepare('UPDATE shares SET label=?,expires_at=?,allow_download=? WHERE id=? AND album_id=?');$s->execute([trim($_POST['label']??''),$expires,!empty($_POST['allow_download'])?1:0,$shareId,$id]);}
        flash('success','Freigabelink aktualisiert.');
    }elseif($action==='delete_share'){$s=$pdo->prepare('DELETE FROM shares WHERE id=? AND album_id=?');$s->execute([(int)($_POST['share_id']??0),$id]);flash('success','Freigabelink gelöscht.');
    }else{
        $shareId=(int)($_POST['share_id']??0);$recipient=trim((string)($_POST['recipient']??''));$message=trim((string)($_POST['message']??''));
        $s=$pdo->prepare('SELECT token FROM shares WHERE id=? AND album_id=?');$s->execute([$shareId,$id]);$shareToken=$s->fetchColumn();
        if(!$shareToken||!filter_var($recipient,FILTER_VALIDATE_EMAIL)){flash('danger',t('mail.invalid_recipient'));}
        else{$url=base_url('s/'.rawurlencode((string)$shareToken));$coverUrl=!empty($album['cover_file'])?base_url('social_cover.php?token='.rawurlencode((string)$shareToken)):null;$html=album_share_mail_html($album,$url,$message,$coverUrl);try{if(!send_system_mail($recipient,t('mail.share_subject',replace:['album'=>$album['title']]),$html))throw new RuntimeException(t('mail.send_failed'));flash('success',t('mail.share_sent'));}catch(Throwable $e){flash('danger',$e->getMessage());}}
    }
    redirect('admin/album_edit.php?id='.$id.'#freigaben');
}
$tracks=[];$shares=[];$collaborators=[];$availableUsers=[];
if($id){$s=$pdo->prepare('SELECT * FROM tracks WHERE album_id=? ORDER BY disc_no,track_no,id');$s->execute([$id]);$tracks=$s->fetchAll();music_share_backfill_track_durations($pdo,$tracks);$s=$pdo->prepare('SELECT * FROM shares WHERE album_id=? ORDER BY created_at DESC');$s->execute([$id]);$shares=$s->fetchAll();$s=$pdo->prepare("SELECT u.id,u.username,u.email FROM album_collaborators ac JOIN users u ON u.id=ac.user_id WHERE ac.album_id=? ORDER BY COALESCE(NULLIF(u.email,''),u.username)");$s->execute([$id]);$collaborators=$s->fetchAll();if(can_manage_album_access($id)){$s=$pdo->prepare("SELECT id,username,email FROM users WHERE is_active=1 AND role='user' AND id<>(SELECT owner_user_id FROM albums WHERE id=?) AND id NOT IN (SELECT user_id FROM album_collaborators WHERE album_id=?) ORDER BY COALESCE(NULLIF(email,''),username)");$s->execute([$id,$id]);$availableUsers=$s->fetchAll();$admins=$pdo->query("SELECT id,username,email FROM users WHERE is_active=1 AND role='admin' ORDER BY COALESCE(NULLIF(email,''),username)")->fetchAll();}}
render_header($id?t('text.album.verwalten'):t('text.neues.album'),true);
?>
